def _calendars_schema(data: dict[str, Any]) -> vol.Schema:
    """Integration-wide calendar settings (shared, not EV-specific)."""

    def d(key):
        return data.get(key, DEFAULTS.get(key))

    return vol.Schema(
        {
            vol.Optional(
                CONF_CALENDARS, default=list(d(CONF_CALENDARS) or [])
            ): selector.EntitySelector(
                selector.EntitySelectorConfig(domain="calendar", multiple=True)
            ),
            vol.Optional(
                CONF_GMAPS_API_KEY, default=d(CONF_GMAPS_API_KEY) or vol.UNDEFINED
            ): selector.TextSelector(
                selector.TextSelectorConfig(type=selector.TextSelectorType.PASSWORD)
            ),
            vol.Optional(
                CONF_TRAVEL_MARGIN_BEFORE_MIN, default=d(CONF_TRAVEL_MARGIN_BEFORE_MIN)
            ): _NUMBER(_NUM(min=0, max=240, step=5, unit_of_measurement="min", mode="box")),
            vol.Optional(
                CONF_TRAVEL_MARGIN_AFTER_MIN, default=d(CONF_TRAVEL_MARGIN_AFTER_MIN)
            ): _NUMBER(_NUM(min=0, max=240, step=5, unit_of_measurement="min", mode="box")),
        }
    )


def _ev_schema(data: dict[str, Any]) -> vol.Schema:
    def d(key):
        return data.get(key, DEFAULTS.get(key))

    return vol.Schema(
        {
            vol.Required(CONF_EV_ENABLED, default=d(CONF_EV_ENABLED)): selector.BooleanSelector(),
            vol.Optional(CONF_EV_SOC_SENSOR, default=d(CONF_EV_SOC_SENSOR) or vol.UNDEFINED): _entity(["sensor", "input_number", "number"]),
            vol.Optional(
                CONF_EV_ODOMETER_SENSOR, default=d(CONF_EV_ODOMETER_SENSOR) or vol.UNDEFINED
            ): _entity(["sensor", "input_number", "number"]),
            vol.Optional(
                CONF_EV_CHARGING_SENSOR, default=d(CONF_EV_CHARGING_SENSOR) or vol.UNDEFINED
            ): _entity(["binary_sensor", "switch", "sensor"]),
            vol.Optional(
                CONF_EV_ENERGY_ADDED_SENSOR, default=d(CONF_EV_ENERGY_ADDED_SENSOR) or vol.UNDEFINED
            ): _entity("sensor"),
            vol.Optional(
                CONF_EV_CHARGE_METER_SENSOR, default=d(CONF_EV_CHARGE_METER_SENSOR) or vol.UNDEFINED
            ): _entity("sensor"),
            vol.Optional(
                CONF_EV_LOCATION_SENSOR, default=d(CONF_EV_LOCATION_SENSOR) or vol.UNDEFINED
            ): _entity(["device_tracker", "binary_sensor", "person"]),
            vol.Optional(
                CONF_EV_PRESENCE_ENTITIES, default=list(d(CONF_EV_PRESENCE_ENTITIES) or [])
            ): selector.EntitySelector(
                selector.EntitySelectorConfig(
                    domain=["device_tracker", "person", "binary_sensor"], multiple=True
                )
            ),
            vol.Optional(
                CONF_EV_CALENDAR_KEYWORD, default=d(CONF_EV_CALENDAR_KEYWORD)
            ): selector.TextSelector(),
            vol.Optional(CONF_EV_CHARGER_KW, default=d(CONF_EV_CHARGER_KW)): _NUMBER(
                _NUM(min=1, max=22, step=0.1, unit_of_measurement="kW", mode="box")
            ),
            vol.Optional(
                CONF_EV_CHARGER_PHASES, default=str(d(CONF_EV_CHARGER_PHASES))
            ): selector.SelectSelector(
                selector.SelectSelectorConfig(
                    options=["1", "3"],
                    mode=selector.SelectSelectorMode.DROPDOWN,
                )
            ),
            vol.Optional(
                CONF_EV_PREFER_CONTIGUOUS, default=bool(d(CONF_EV_PREFER_CONTIGUOUS))
            ): selector.BooleanSelector(),
            vol.Optional(
                CONF_EV_CONTIGUOUS_MAX_EXTRA_PCT,
                default=d(CONF_EV_CONTIGUOUS_MAX_EXTRA_PCT),
            ): _NUMBER(_NUM(min=0, max=100, step=1, unit_of_measurement="%", mode="box")),
            vol.Optional(
                CONF_EV_PREFER_EARLY, default=bool(d(CONF_EV_PREFER_EARLY))
            ): selector.BooleanSelector(),
            vol.Optional(
                CONF_EV_EARLY_MAX_EXTRA_PCT, default=d(CONF_EV_EARLY_MAX_EXTRA_PCT)
            ): _NUMBER(_NUM(min=0, max=100, step=1, unit_of_measurement="%", mode="box")),
            # Flat AC charging efficiency at full power (0.91 = 91 %); the
            # charger always runs at full power, short needs get a planned
            # duration (the ev_charge_minutes sensor) instead of less power.
            vol.Optional(
                CONF_EV_CHARGE_EFFICIENCY, default=d(CONF_EV_CHARGE_EFFICIENCY)
            ): _NUMBER(_NUM(min=0.5, max=1, step=0.01, mode="slider")),
        }
    )


def _charge_curve_schema(data: dict[str, Any]) -> vol.Schema:
    """One max-charge-power field per SoC band.

    Each band defaults to its stored value (matched by ``soc_from``) or, if the
    curve is not configured yet, to the flat inverter charge limit — so leaving
    every field at its default reproduces today's flat behaviour.
    """
    stored = {
        int(seg["soc_from"]): float(seg["max_kw"])
        for seg in (data.get(CONF_CHARGE_CURVE) or [])
    }
    flat = float(
        data.get(CONF_INVERTER_MAX_CHARGE_KW, DEFAULTS[CONF_INVERTER_MAX_CHARGE_KW])
    )
    fields: dict[Any, Any] = {}
    for band in CHARGE_CURVE_BANDS:
        lo, _hi = band
        fields[
            vol.Required(charge_curve_band_key(band), default=stored.get(lo, flat))
        ] = _NUMBER(_NUM(min=0, max=50, step=0.1, unit_of_measurement="kW", mode="box"))
    # Power-dependent charge efficiency, entered as "power:efficiency%" pairs
    # (power in W or kW — values above 100 are read as watts), e.g.
    # "500:80, 1000:91, 2000:93, 4000:93, 7000:88". Empty → flat efficiency.
    fields[
        vol.Optional(
            EFFICIENCY_CURVE_FIELD,
            default=_efficiency_curve_text(data.get(CONF_CHARGE_EFFICIENCY_CURVE)),
        )
    ] = selector.TextSelector()
    return vol.Schema(fields)


# Transient form-field key for the efficiency-curve text (parsed into
# CONF_CHARGE_EFFICIENCY_CURVE segments; never stored itself).
EFFICIENCY_CURVE_FIELD = "charge_efficiency_curve_text"

