file.content:
  gap: 8px;
  margin-bottom: 12px;
}
.debug-btn {
  background: var(--card-background-color, #fff);
  color: var(--primary-text-color);
  border: 1px solid var(--divider-color, rgba(127, 127, 127, 0.3));
  border-radius: 6px;
  padding: 7px 14px;
  font-size: 13px;
  cursor: pointer;
}
.debug-btn:hover {
  background: var(--secondary-background-color, rgba(127, 127, 127, 0.12));
}
.debug-btn.primary {
  background: var(--primary-color, #03a9f4);
  color: var(--text-primary-color, #fff);
  border-color: transparent;
}
.debug-btn[disabled] {
  opacity: 0.6;
  cursor: default;
}
.debug-json {
  max-height: 420px;
  overflow: auto;
  background: var(--secondary-background-color, rgba(127, 127, 127, 0.1));
  border: 1px solid var(--divider-color, rgba(127, 127, 127, 0.3));
  border-radius: 6px;
  padding: 10px;
  font-family: var(--code-font-family, monospace);
  font-size: 11px;
  line-height: 1.4;
  white-space: pre;
  margin: 0;
}
.chart {
  width: 100%;
  height: auto;
  display: block;
}
.ax {
  fill: var(--secondary-text-color);
  font-size: 10px;
}
.ax.unit {
  font-weight: 600;
}
.ax.day {
  font-weight: 600;
}
.ax.now {
  fill: var(--primary-text-color);
  font-weight: 600;
}
.stat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.stat {
  display: flex;
  flex-direction: column;
}
.stat .k {
  font-size: 12px;
  color: var(--secondary-text-color);
}
.stat .v {
  font-size: 18px;
  font-weight: 600;
}
.check {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
}
.muted {
  color: var(--secondary-text-color);
  font-size: 13px;
}
.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.dot.ok {
  background: var(--success-color, #43a047);
}
.dot.bad {
  background: var(--error-color, #d33);
}
.dot.warn {
  background: var(--warning-color, #f9a825);
}
.dot.skip {
  background: var(--disabled-text-color, #9e9e9e);
}
.diag-badge {
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
  margin-left: 8px;
}
.diag-badge.ok {
  background: rgba(67, 160, 71, 0.15);
  color: var(--success-color, #43a047);
}
.diag-badge.bad {
  background: rgba(211, 51, 51, 0.15);
  color: var(--error-color, #d33);
}
